from typing import Optional
from collections import defaultdict, deque

class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self.customers = {}
        self.tickets = {}
        self.queue = defaultdict(deque)
        self.ticket_id = 0
        self.closed_tickets = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self.customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")

        if customer not in self.customers:
            raise ValueError("Customer not found")

        self.ticket_id += 1
        self.tickets[self.ticket_id] = (customer, title, priority, False)
        self._add_to_queue(self.ticket_id)
        return self.ticket_id

    def next_ticket(self) -> Optional[int]:
        for vip in [True, False]:
            for priority in reversed(self.PRIORITIES):
                if self.queue[(vip, priority)]:
                    ticket_id = self.queue[(vip, priority)].popleft()
                    return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self.tickets[ticket_id] = (*self.tickets[ticket_id][:3], True)
        self.closed_tickets.add(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        if ticket_id in self.closed_tickets:
            raise ValueError("Cannot reopen a closed ticket")
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self.tickets[ticket_id] = (*self.tickets[ticket_id][:3], False)
        self._add_to_queue(ticket_id)

    def _add_to_queue(self, ticket_id: int):
        customer, _, priority, _ = self.tickets[ticket_id]
        vip = self.customers[customer]
        self.queue[(vip, priority)].append(ticket_id)
```

### Example usage:
```python
helpdesk = Helpdesk()
helpdesk.add_customer("John Doe", vip=True)
helpdesk.add_customer("Jane Doe")

ticket1 = helpdesk.open_ticket("John Doe", "Urgent issue", priority="critical")
ticket2 = helpdesk.open_ticket("Jane Doe", "Normal issue")
ticket3 = helpdesk.open_ticket("John Doe", "High priority issue", priority="high")

print(helpdesk.next_ticket())  # Should print ticket1
print(helpdesk.next_ticket())  # Should print ticket3
print(helpdesk.next_ticket())  # Should print ticket2

helpdesk.close(ticket1)
try:
    helpdesk.reopen(ticket1)
except ValueError as e:
    print(e)  # Should print "Cannot reopen a closed ticket"
```

